"use strict";(self.webpackChunkneuronpedia_docs=self.webpackChunkneuronpedia_docs||[]).push([[820],{7691:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","label":"Introduction","href":"/","docId":"introduction","unlisted":false},{"type":"category","label":"Getting Started","collapsible":true,"collapsed":false,"items":[{"type":"link","label":"Key Concepts","href":"/getting-started/key-concepts","docId":"getting-started/key-concepts","unlisted":false},{"type":"link","label":"Find Models and Data","href":"/getting-started/find-resources","docId":"getting-started/find-resources","unlisted":false},{"type":"link","label":"Accounts, API Keys & Limits","href":"/getting-started/accounts","docId":"getting-started/accounts","unlisted":false}],"href":"/category/getting-started"},{"type":"category","label":"Sparse Autoencoders","collapsible":true,"collapsed":false,"items":[{"type":"link","label":"Feature Dashboards","href":"/sparse-autoencoders/feature-dashboards","docId":"sparse-autoencoders/feature-dashboards","unlisted":false},{"type":"link","label":"Search","href":"/sparse-autoencoders/search","docId":"sparse-autoencoders/search","unlisted":false},{"type":"link","label":"Auto-Interp","href":"/sparse-autoencoders/auto-interp","docId":"sparse-autoencoders/auto-interp","unlisted":false},{"type":"link","label":"Lists & Embed Lists","href":"/sparse-autoencoders/lists","docId":"sparse-autoencoders/lists","unlisted":false},{"type":"link","label":"Embeds (iframe)","href":"/sparse-autoencoders/embeds","docId":"sparse-autoencoders/embeds","unlisted":false},{"type":"link","label":"Upload Your SAEs","href":"/sparse-autoencoders/upload-saes","docId":"sparse-autoencoders/upload-saes","unlisted":false}],"href":"/sparse-autoencoders/overview"},{"type":"link","label":"Steering","href":"/steering","docId":"steering","unlisted":false},{"type":"category","label":"Circuit Tracing","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Generate Graphs","href":"/circuit-tracing/generate-graphs","docId":"circuit-tracing/generate-graphs","unlisted":false},{"type":"link","label":"Explore a Graph","href":"/circuit-tracing/explore-graphs","docId":"circuit-tracing/explore-graphs","unlisted":false},{"type":"link","label":"Steer from a Graph","href":"/circuit-tracing/steer-graphs","docId":"circuit-tracing/steer-graphs","unlisted":false},{"type":"link","label":"Attention in Graphs (LORSA)","href":"/circuit-tracing/attention-lorsa","docId":"circuit-tracing/attention-lorsa","unlisted":false},{"type":"link","label":"Upload Your Graphs","href":"/circuit-tracing/upload-graphs","docId":"circuit-tracing/upload-graphs","unlisted":false}],"href":"/circuit-tracing/overview"},{"type":"link","label":"Attention Heads (HeadVis)","href":"/attention-heads","docId":"attention-heads","unlisted":false},{"type":"link","label":"Jacobian Lens","href":"/jacobian-lens","docId":"jacobian-lens","unlisted":false},{"type":"link","label":"Natural Language Autoencoders","href":"/natural-language-autoencoders","docId":"natural-language-autoencoders","unlisted":false},{"type":"link","label":"Assistant Axis","href":"/assistant-axis","docId":"assistant-axis","unlisted":false},{"type":"category","label":"Research Releases","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Temporal Feature Analysis","href":"/research-releases/temporal-feature-analysis","docId":"research-releases/temporal-feature-analysis","unlisted":false},{"type":"link","label":"Weight-Sparse Transformers","href":"/research-releases/weight-sparse-transformers","docId":"research-releases/weight-sparse-transformers","unlisted":false}],"href":"/research-releases/overview"},{"type":"category","label":"API & Data","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"API","href":"/api-and-data/api","docId":"api-and-data/api","unlisted":false},{"type":"link","label":"Python Library","href":"/api-and-data/python-library","docId":"api-and-data/python-library","unlisted":false},{"type":"link","label":"Exports","href":"/api-and-data/exports","docId":"api-and-data/exports","unlisted":false}],"href":"/category/api--data"},{"type":"category","label":"Open Source","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Neuronpedia Is Open Source","href":"/open-source/self-hosting","docId":"open-source/self-hosting","unlisted":false},{"type":"link","label":"interp-engine","href":"/open-source/interp-engine","docId":"open-source/interp-engine","unlisted":false}],"href":"/category/open-source"},{"type":"link","label":"Feedback & Support","href":"/feedback","docId":"feedback","unlisted":false}]},"docs":{"api-and-data/api":{"id":"api-and-data/api","title":"API","description":"Neuronpedia has a public API for almost everything on the website. You can get features and explanations, test activations, steer, search, make graphs, run the Jacobian Lens, use NLAs, and upload data.","sidebar":"tutorialSidebar"},"api-and-data/exports":{"id":"api-and-data/exports","title":"Exports","description":"You can download Neuronpedia\'s data. This is faster than the API for a large number of features, and it does not use your rate limit.","sidebar":"tutorialSidebar"},"api-and-data/python-library":{"id":"api-and-data/python-library","title":"Python Library","description":"The Neuronpedia Python library makes it easy to use the API from Python.","sidebar":"tutorialSidebar"},"assistant-axis":{"id":"assistant-axis","title":"Assistant Axis","description":"The Assistant Axis is a direction in a model\'s activations that measures how much the model acts like its normal \\"assistant\\" persona. Anthropic found that models can drift away from this persona during a chat. When they drift, they are more likely to give harmful, sycophantic, or jailbroken answers. Activation capping stops the drift: it keeps the model\'s position on the axis inside its normal range.","sidebar":"tutorialSidebar"},"attention-heads":{"id":"attention-heads","title":"Attention Heads (HeadVis)","description":"HeadVis is a tool to explore attention heads. It is by Anthropic (Luger, Kamath, et al.). Neuronpedia has HeadVis dashboards for more than 36,000 attention heads in 37 models.","sidebar":"tutorialSidebar"},"circuit-tracing/attention-lorsa":{"id":"circuit-tracing/attention-lorsa","title":"Attention in Graphs (LORSA)","description":"Standard attribution graphs replace only the MLPs with transcoders. OpenMOSS extended this to also replace attention, which they call Complete Replacement Models (CRMs). Neuronpedia can generate CRM graphs for Qwen3-1.7B.","sidebar":"tutorialSidebar"},"circuit-tracing/explore-graphs":{"id":"circuit-tracing/explore-graphs","title":"Explore a Graph","description":"A graph page has four parts. We\'ll use the Dallas graph as the example.","sidebar":"tutorialSidebar"},"circuit-tracing/generate-graphs":{"id":"circuit-tracing/generate-graphs","title":"Generate Graphs","description":"You can make your own attribution graph from a prompt. It takes about a minute.","sidebar":"tutorialSidebar"},"circuit-tracing/overview":{"id":"circuit-tracing/overview","title":"Circuit Tracing","description":"Circuit tracing shows the steps a model takes inside to get from a prompt to its next token. Neuronpedia makes attribution graphs for your prompts, and gives you tools to explore, label, steer, and share them.","sidebar":"tutorialSidebar"},"circuit-tracing/steer-graphs":{"id":"circuit-tracing/steer-graphs","title":"Steer from a Graph","description":"A subgraph is a hypothesis. To test it, you can steer the model from the graph page: turn features up or down, then look at how the output changes.","sidebar":"tutorialSidebar"},"circuit-tracing/upload-graphs":{"id":"circuit-tracing/upload-graphs","title":"Upload Your Graphs","description":"You can make graphs with a different library, a different model, or your own transcoders, and then upload them to Neuronpedia. Uploaded graphs have the same tools as generated graphs: subgraphs, supernodes, feature details, and sharing.","sidebar":"tutorialSidebar"},"feedback":{"id":"feedback","title":"Feedback & Support","description":"There is nothing we like more than fixing bugs and building the features that you ask for. Send us your most ambitious ideas. We will give you credit for them, if you want.","sidebar":"tutorialSidebar"},"getting-started/accounts":{"id":"getting-started/accounts","title":"Accounts, API Keys & Limits","description":"You can use most of Neuronpedia without an account. Sign in to save your work and to use some tools.","sidebar":"tutorialSidebar"},"getting-started/find-resources":{"id":"getting-started/find-resources","title":"Find Models and Data","description":"Neuronpedia has data for many models, including Gemma, Llama, Qwen, GPT-2, GPT-OSS, DeepSeek, and Pythia. There are many ways to find what you want.","sidebar":"tutorialSidebar"},"getting-started/key-concepts":{"id":"getting-started/key-concepts","title":"Key Concepts","description":"Neuronpedia organizes data in a few levels. If you know these terms, the URLs and the API are easy to use.","sidebar":"tutorialSidebar"},"introduction":{"id":"introduction","title":"Introduction","description":"Neuronpedia Logo","sidebar":"tutorialSidebar"},"jacobian-lens":{"id":"jacobian-lens","title":"Jacobian Lens","description":"The Jacobian Lens (J-lens) shows the concepts that a model \\"holds in mind\\" at each token. Gurnee et al. argue that models have a global workspace, in what they call the Jacobian space, or J-space. A J-lens is \\"fitted\\" for each model, and it reads the J-space as a list of tokens.","sidebar":"tutorialSidebar"},"natural-language-autoencoders":{"id":"natural-language-autoencoders","title":"Natural Language Autoencoders","description":"Natural Language Autoencoders (NLAs) translate a model\'s activations into plain English, so that you can read what the model is \\"thinking\\" at a token. Neuronpedia hosts NLAs from Anthropic and from the community.","sidebar":"tutorialSidebar"},"open-source/interp-engine":{"id":"open-source/interp-engine","title":"interp-engine","description":"interp-engine is the library that Neuronpedia uses to run models. It does all of Neuronpedia\'s work that needs a model: activations, steering, the Jacobian Lens, NLAs, and circuit tracing. It is open source, and you can use it for your own research.","sidebar":"tutorialSidebar"},"open-source/self-hosting":{"id":"open-source/self-hosting","title":"Neuronpedia Is Open Source","description":"All of Neuronpedia\'s code is open source, under the Apache 2.0 license.","sidebar":"tutorialSidebar"},"research-releases/overview":{"id":"research-releases/overview","title":"Research Releases","description":"Neuronpedia works with research groups to put their work online, so that other researchers can use it right away. Each release has its own page, and most have interactive tools.","sidebar":"tutorialSidebar"},"research-releases/temporal-feature-analysis":{"id":"research-releases/temporal-feature-analysis","title":"Temporal Feature Analysis","description":"Temporal Feature Analysis is a method by Lubana, Rager, Hindupur, et al. It finds features that capture both the context of a text (for example, \\"this is a story\\") and local information (for example, \\"this token is a number\\").","sidebar":"tutorialSidebar"},"research-releases/weight-sparse-transformers":{"id":"research-releases/weight-sparse-transformers","title":"Weight-Sparse Transformers","description":"OpenAI trained weight-sparse transformers (Gao et al.). Most of their weights are zero, so their circuits are small and easier to understand. Neuronpedia has a visualizer and dashboards for the Python code model, circuitgpt-python.","sidebar":"tutorialSidebar"},"sparse-autoencoders/auto-interp":{"id":"sparse-autoencoders/auto-interp","title":"Auto-Interp","description":"Most features on Neuronpedia have explanations that AI models wrote. We show a feature\'s top activations to a model, like GPT, Claude, or Gemini, and ask it to explain what the feature is about. This is called automatic interpretability, or auto-interp.","sidebar":"tutorialSidebar"},"sparse-autoencoders/embeds":{"id":"sparse-autoencoders/embeds","title":"Embeds (iframe)","description":"Basics","sidebar":"tutorialSidebar"},"sparse-autoencoders/feature-dashboards":{"id":"sparse-autoencoders/feature-dashboards","title":"Feature Dashboards","description":"A feature dashboard shows everything that we know about one feature. It has the feature\'s top activations, its logits, its explanations, and tools to test and steer it.","sidebar":"tutorialSidebar"},"sparse-autoencoders/lists":{"id":"sparse-autoencoders/lists","title":"Lists & Embed Lists","description":"Lists let you save features and link to them in one page. People often use them to show similar features, but you can use them for any purpose.","sidebar":"tutorialSidebar"},"sparse-autoencoders/overview":{"id":"sparse-autoencoders/overview","title":"Sparse Autoencoders","description":"Sparse Autoencoders (SAEs) find interpretable features in a model\'s activations. Each feature is a \\"thing that the model knows\\", like \\"the Golden Gate Bridge\\" or \\"text in French\\". Here is an explainer on SAEs.","sidebar":"tutorialSidebar"},"sparse-autoencoders/search":{"id":"sparse-autoencoders/search","title":"Search","description":"Neuronpedia has three ways to find features. Open them from Search in the top menu.","sidebar":"tutorialSidebar"},"sparse-autoencoders/upload-saes":{"id":"sparse-autoencoders/upload-saes","title":"Upload Your SAEs","description":"There are two ways to put your SAEs (or transcoders, or other features) on Neuronpedia.","sidebar":"tutorialSidebar"},"steering":{"id":"steering","title":"Steering","description":"Steering changes a model\'s output by adding a feature (or a vector) to the model\'s activations while it writes. It is like Anthropic\'s \\"Golden Gate Claude\\" demo, but you can use any feature on Neuronpedia.","sidebar":"tutorialSidebar"}}}}')}}]);